begin;
-- User-authorized supplier import. No prices, publication, permissions or existing items are changed.
do $supplier_import$
declare actor uuid; entry jsonb; item_id uuid; existing public.catalog_items; created integer:=0; skipped integer:=0;
begin
 if (select count(*) from public.staff_memberships where role='admin' and is_active=true)<>1 then raise exception 'Select the intended active administrator before importing.'; end if;
 select user_id into actor from public.staff_memberships where role='admin' and is_active=true;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 for entry in select value from jsonb_array_elements('[{"code": "AKIJ-3D-BLACK-PB-18", "name": "Akij 3D-Black - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/3d-black/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-AKIJ-DARK-OAK-PB-18", "name": "Akij Dark Oak - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/akij-dark-oak/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-AKIJ-OAK-PB-18", "name": "Akij Oak - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/akij-oak/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-AMERICAN-TEAK-PB-18", "name": "Akij American Teak - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/american-teak/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-ALBINO-OAK-PB-18", "name": "Akij Albino Oak - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/albino-oak/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-BEECH-PB-18", "name": "Akij Beech - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/beech/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-ANATURE-PB-18", "name": "Akij Anature - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/anature/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-ANTIC-PB-18", "name": "Akij Antic - Particle Board 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/product/antic/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-RAW-MDF-6", "name": "Akij Raw MDF Board 6 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/mdf/", "thickness_mm": 6, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "AKIJ-MR-PLYWOOD-18", "name": "Akij MR Grade Plywood 18 mm", "source_name": "Akij Board (grain unverified; height locked)", "source_url": "https://akijboard.com/plywood/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "SUPER-PLAIN-MDF-18", "name": "Super Board Plain MDF Board 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/plain-mdf/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-PPB-WOOD-CHIPS-16", "name": "Super Board Plain Particle Board (Wood Chips) 16 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/plain-particle-board-wood-chips/", "thickness_mm": 16, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-PPB-JUTE-CHIPS-18", "name": "Super Board Plain Particle Board (Jute Chips) 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/plain-particle-board-jute-chips/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-MELAMINE-BOARD-126-18", "name": "Super Board Melamine Board 126 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/melamine-board-126/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-MELAMINE-BOARD-811-18", "name": "Super Board Melamine Board 811 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/melamine-board-811/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-MELAMINE-BOARD-810-18", "name": "Super Board Melamine Board 810 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/melamine-board-810/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-MELAMINE-BOARD-807-18", "name": "Super Board Melamine Board 807 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/melamine-board-807/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-SUPER-TEAK-18", "name": "Super Board Super Teak 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/super-teak/", "thickness_mm": 18, "sheet_width_mm": 1220, "sheet_height_mm": 2440, "grain_direction": "height"}, {"code": "SUPER-PET-LAMINATION-3014-18", "name": "Super Board PET LAMINATION 3014 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/pet-lamination-3014/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}, {"code": "SUPER-PET-LAMINATION-3008-18", "name": "Super Board PET LAMINATION 3008 18 mm", "source_name": "SUPERBOARD (grain unverified; height locked)", "source_url": "https://superboard.com.bd/product/pet-lamination-3008/", "thickness_mm": 18, "sheet_width_mm": 1219.2, "sheet_height_mm": 2438.4, "grain_direction": "height"}]'::jsonb) loop
  select * into existing from public.catalog_items where kind='board' and code=entry->>'code';
  if found then
   if existing.source_url is distinct from entry->>'source_url' or existing.name is distinct from entry->>'name'
    or not exists(select 1 from public.board_skus b where b.item_id=existing.id and b.thickness_mm=(entry->>'thickness_mm')::numeric and b.sheet_width_mm=(entry->>'sheet_width_mm')::numeric and b.sheet_height_mm=(entry->>'sheet_height_mm')::numeric) then
    raise exception 'Existing catalog code differs from prepared import: %',entry->>'code';
   end if;
   skipped:=skipped+1;
  else
   item_id:=public.cutplan_catalog_change(jsonb_build_object('action','create','kind','board','code',entry->>'code','name',entry->>'name','details',jsonb_build_object('thickness_mm',entry->'thickness_mm','sheet_width_mm',entry->'sheet_width_mm','sheet_height_mm',entry->'sheet_height_mm','grain_direction',entry->>'grain_direction')));
   update public.catalog_items set source_name=entry->>'source_name',source_url=entry->>'source_url',source_captured_at='2026-10-25T14:33:03.297512+00:00'::timestamptz where id=item_id;
   created:=created+1;
  end if;
 end loop;
 raise notice 'Supplier boards created: %, already present: %',created,skipped;
end; $supplier_import$;
commit;
